From 38bfba7e5151750348a178f68b6cf6f66cd28647 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:47:46 +0100
Subject: [PATCH] daemon: Count down the seconds in the Battery Critical
 notification

The Battery Critical notification always said the system would sleep,
hibernate or shut down "in 60 seconds", even as that time ran out. It
now updates every second to show how many seconds are actually left.

BUG: 491632
---
 daemon/powerdevilcore.cpp | 35 ++++++++++++++++++++++++++++++++---
 daemon/powerdevilcore.h   |  2 ++
 2 files changed, 34 insertions(+), 3 deletions(-)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..155a07c28 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -56,6 +56,7 @@ Core::Core(QObject *parent)
     : QObject(parent)
     , m_hasDualGpu(false)
     , m_criticalBatteryTimer(new QTimer(this))
+    , m_criticalBatteryCountdownTimer(new QTimer(this))
     , m_activityConsumer(new KActivities::Consumer(this))
     , m_pendingWakeupEvent(true)
 {
@@ -181,6 +182,8 @@ void Core::onControllersReady()
     m_criticalBatteryTimer->setSingleShot(true);
     m_criticalBatteryTimer->setInterval(60000);
     connect(m_criticalBatteryTimer, &QTimer::timeout, this, &Core::onCriticalBatteryTimerExpired);
+    m_criticalBatteryCountdownTimer->setInterval(1000);
+    connect(m_criticalBatteryCountdownTimer, &QTimer::timeout, this, &Core::updateCriticalBatteryCountdown);

     // wait until the notification system is set up before firing notifications
     // to avoid them showing ontop of ksplash...
@@ -630,7 +633,6 @@ void Core::handleCriticalBattery(int percent)

     switch (static_cast<PowerButtonAction>(m_globalSettings->batteryCriticalAction())) {
     case PowerButtonAction::Shutdown: {
-        m_criticalBatteryNotification->setText(i18n("The system will shut down in 60 seconds."));
         auto action =
             m_criticalBatteryNotification->addAction(i18nc("@action:button Shut down without waiting for the battery critical timer", "Shut Down Now"));
         connect(action, &KNotificationAction::activated, this, &Core::triggerCriticalBatteryAction);
@@ -638,7 +640,6 @@ void Core::handleCriticalBattery(int percent)
         break;
     }
     case PowerButtonAction::Hibernate: {
-        m_criticalBatteryNotification->setText(i18n("The system will hibernate in 60 seconds."));
         auto action = m_criticalBatteryNotification->addAction(
             i18nc("@action:button Enter hibernation mode without waiting for the battery critical timer", "Hibernate Now"));
         connect(action, &KNotificationAction::activated, this, &Core::triggerCriticalBatteryAction);
@@ -646,7 +647,6 @@ void Core::handleCriticalBattery(int percent)
         break;
     }
     case PowerButtonAction::Sleep: {
-        m_criticalBatteryNotification->setText(i18n("The system will go to sleep in 60 seconds."));
         auto action =
             m_criticalBatteryNotification->addAction(i18nc("@action:button Suspend to ram without waiting for the battery critical timer", "Sleep Now"));
         connect(action, &KNotificationAction::activated, this, &Core::triggerCriticalBatteryAction);
@@ -659,6 +659,11 @@ void Core::handleCriticalBattery(int percent)
         break;
     }

+    if (m_criticalBatteryTimer->isActive()) {
+        updateCriticalBatteryCountdown();
+        m_criticalBatteryCountdownTimer->start();
+    }
+
     auto cancelAction =
         m_criticalBatteryNotification->addAction(i18nc("Cancel timeout that will automatically put system to sleep because of low battery", "Cancel"));
     connect(cancelAction, &KNotificationAction::activated, this, [this] {
@@ -668,6 +673,29 @@ void Core::handleCriticalBattery(int percent)
     m_criticalBatteryNotification->sendEvent();
 }

+void Core::updateCriticalBatteryCountdown()
+{
+    if (!m_criticalBatteryNotification || !m_criticalBatteryTimer->isActive()) {
+        m_criticalBatteryCountdownTimer->stop();
+        return;
+    }
+
+    const int seconds = qRound(m_criticalBatteryTimer->remainingTime() / 1000.0);
+    switch (static_cast<PowerButtonAction>(m_globalSettings->batteryCriticalAction())) {
+    case PowerButtonAction::Shutdown:
+        m_criticalBatteryNotification->setText(i18np("The system will shut down in 1 second.", "The system will shut down in %1 seconds.", seconds));
+        break;
+    case PowerButtonAction::Hibernate:
+        m_criticalBatteryNotification->setText(i18np("The system will hibernate in 1 second.", "The system will hibernate in %1 seconds.", seconds));
+        break;
+    case PowerButtonAction::Sleep:
+        m_criticalBatteryNotification->setText(i18np("The system will go to sleep in 1 second.", "The system will go to sleep in %1 seconds.", seconds));
+        break;
+    default:
+        break;
+    }
+}
+
 void Core::updateBatteryNotifications(int percent)
 {
     if (m_lowBatteryNotification) {
@@ -827,6 +855,7 @@ void Core::triggerCriticalBatteryAction()
 void Core::cancelCriticalBatteryNotification()
 {
     m_criticalBatteryTimer->stop();
+    m_criticalBatteryCountdownTimer->stop();
     if (m_criticalBatteryNotification) {
         m_criticalBatteryNotification->close();
         m_criticalBatteryNotification = nullptr;
diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..ba298b05b 100644
--- a/daemon/powerdevilcore.h
+++ b/daemon/powerdevilcore.h
@@ -140,6 +140,7 @@ private:
     void updateBatteryNotifications(int percent);
     void triggerCriticalBatteryAction();
     void cancelCriticalBatteryNotification();
+    void updateCriticalBatteryCountdown();

     void readChargeThreshold();
     void readBatteryConservationMode();
@@ -177,6 +178,7 @@ private:

     QPointer<KNotification> m_lowBatteryNotification;
     QTimer *const m_criticalBatteryTimer;
+    QTimer *const m_criticalBatteryCountdownTimer;
     QPointer<KNotification> m_criticalBatteryNotification;
     QPointer<KNotification> m_powerCordPluggedInNotification;
     QPointer<KNotification> m_powerCordUnpluggedNotification;
-- 
2.53.0
